from typing import Any


class EnvCfgError(Exception):
    """Raised when env var coercion fails or an env var has no default."""

    def __init__(self, key: str, expected_type: str, value: str):
        self.key = key
        self.expected_type = expected_type
        self.value = value
        super().__init__(f"{key}: expected {expected_type}, got "{value}"")


def coerce(value: str, target_type: type) -> Any:
    """Coerce a string to the given type, raising EnvCfgError on failure."""
    if target_type is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(value, "int", value)
    if target_type is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(value, "float", value)
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(value, "bool", value)
    if target_type is str:
        return value
    raise EnvCfgError(value, str(target_type), value)


def _merge(base: dict, override: dict) -> dict:
    """Shallow merge override into base."""
    result = base.copy()
    result.update(override)
    return result


