import os
import pytest
from envcfg import load, EnvCfgError, coerce


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    os.environ.clear()
    cfg = load({"a": 1, "b": 2}, toml_path="/dev/null")
    assert cfg == {"a": 1, "b": 2}


def test_env_overrides_defaults():
    os.environ["APP__A"] = "10"
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 10, "b": 2}


def test_env_overrides_toml():
    os.environ["APP__A"] = "100"
    cfg = load({"a": 1}, toml_path="/dev/null")
    assert cfg == {"a": 100}


def test_nested_keys():
    os.environ["APP__SERVER__PORT"] = "8080"
    os.environ["APP__DATABASE__HOST"] = "localhost"
    cfg = load({"server": {"port": 80}, "database": {"host": "db.example.com"}})
    assert cfg == {
        "server": {"port": 8080},
        "database": {"host": "localhost"},
    }


def test_missing_toml_file_is_skipped():
    cfg = load({"a": 1}, toml_path="/nonexistent.toml")
    assert cfg == {"a": 1}


def test_env_var_without_default_raises():
    os.environ["APP__X"] = "1"
    with pytest.raises(EnvCfgError) as exc:
        load({"a": 1})
    assert "X" in str(exc.value)


def test_coerce_int():
    assert coerce("42", int) == 42


def test_coerce_float():
    assert coerce("3.14", float) == 3.14


def test_coerce_bool_true():
    assert coerce("true", bool) is True
    assert coerce("True", bool) is True
    assert coerce("1", bool) is True
    assert coerce("yes", bool) is True
    assert coerce("Yes", bool) is True


def test_coerce_bool_false():
    assert coerce("false", bool) is False
    assert coerce("False", bool) is False
    assert coerce("0", bool) is False
    assert coerce("no", bool) is False
    assert coerce("No", bool) is False


def test_coerce_bool_invalid():
    with pytest.raises(EnvCfgError):
        coerce("maybe", bool)


def test_coerce_str():
    assert coerce("hello", str) == "hello"


